// On the Aurora PostgreSQL cluster the firm already runs:
//   CREATE EXTENSION IF NOT EXISTS vector;
//   ALTER TABLE clause ADD COLUMN embedding vector(1024);
// The clause, its client, its matter, and its effective_date are the same
// row. The filter is a WHERE, not a cross-system join.
const enablePgvector = 'CREATE EXTENSION IF NOT EXISTS vector;';

