const kb = new CfnKnowledgeBase(this, 'ContractKB', {
  name: 'contract-desk',
  roleArn: kbRole.roleArn,
  knowledgeBaseConfiguration: { type: 'VECTOR', vectorKnowledgeBaseConfiguration: { embeddingModelArn: titanEmbedArn } },
  storageConfiguration: {
    type: 'RDS',
    rdsConfiguration: {
      resourceArn: auroraClusterArn,
      tableName: 'clause',
      fieldMapping: { primaryKeyField: 'clause_id', vectorField: 'embedding', textField: 'text', metadataField: 'metadata' },
    },
  },
});

steps.infrastructure:
// Customer-managed: the knowledge base points at the Aurora/pgvector store
// the firm already runs, mapping to the clause table's own columns. The
// SQL filters and the schema stay. A fully-managed index would re-chunk and
// re-store the clauses, duplicating the matter schema and moving the
// cross-client guarantee into metadata you can get wrong.

