snippets.source:
const kbRole = new Role(this, 'ContractKbRole', {
  assumedBy: new ServicePrincipal('bedrock.amazonaws.com', {
    conditions: {
      StringEquals: { 'aws:SourceAccount': account },
      ArnLike: { 'aws:SourceArn': knowledgeBaseArn },
    },
  }),
});

steps.infrastructure:
// The KB role trusts the Bedrock service principal only when the call is
// for this account (aws:SourceAccount) and this knowledge base
// (aws:SourceArn). Without those conditions the role is a confused deputy:
// another account's knowledge base could induce Bedrock to assume it and
// read this firm's clauses. The source conditions close that.

